"""The data of the stylelint rules, generated by tools/generate_css_data.py."""

import subprocess
import sys
from pathlib import Path

import pytest

from kgcss import _css_data as data

from .stylelint_oracle import skip_reason

ROOT = Path(__file__).resolve().parent.parent


def test_up_to_date_with_the_pinned_stylelint() -> None:
    if (reason := skip_reason()) is not None:
        pytest.skip(reason)
    module = ROOT / 'src' / 'kgcss' / '_css_data.py'
    result = subprocess.run(
        [sys.executable, '-I', str(ROOT / 'tools' / 'generate_css_data.py'), '--check', str(module)],
        capture_output=True,
        text=True,
    )
    assert result.returncode == 0, result.stderr


@pytest.mark.parametrize(
    ('table', 'present', 'absent'),
    [
        (data.CSS_TREE_PROPERTIES, ('color', 'margin-inline', '-webkit-appearance'), ('colr', 'Color')),
        (data.CSS_TREE_DASHED_IDENT_PROPERTIES, ('anchor-name', 'animation-name'), ('color',)),
        (data.CSS_TREE_FUNCTIONS, ('calc', 'rgb', 'var', 'url', 'linear-gradient'), ('foo', 'RGB')),
        (data.AT_KEYWORDS, ('media', 'import', 'font-face', 'layer'), ('foo',)),
        (data.UNITS, ('px', 'em', 'Hz', 'kHz'), ('pix',)),
        (data.PSEUDO_CLASSES, ('hover', 'nth-child', 'is'), ('foo',)),
        (data.PSEUDO_ELEMENTS, ('before', 'marker', 'part'), ('hover',)),
        (data.HTML_TYPE_SELECTORS, ('div', 'p', 'blink'), ('foo',)),
        (data.SVG_TYPE_SELECTORS, ('circle', 'foreignObject'), ('foreignobject',)),
        (data.MEDIA_FEATURE_NAMES, ('width', 'prefers-color-scheme'), ('colr',)),
        (data.SYSTEM_FONT_KEYWORDS, ('caption', 'menu'), ('serif',)),
    ],
)
def test_contents(table: frozenset[str], present: tuple[str, ...], absent: tuple[str, ...]) -> None:
    for name in present:
        assert name in table
    for name in absent:
        assert name not in table


def test_consistency() -> None:
    assert data.CSS_TREE_DASHED_IDENT_PROPERTIES <= data.CSS_TREE_PROPERTIES
    assert data.LEVEL_ONE_AND_TWO_PSEUDO_ELEMENTS <= data.PSEUDO_ELEMENTS
    assert data.A_N_PLUS_B_OF_S_NOTATION_PSEUDO_CLASSES <= data.PSEUDO_CLASSES
    assert data.LENGTH_UNITS <= data.UNITS
    assert all(name == name.lower() for name in data.CSS_TREE_PROPERTIES | data.CSS_TREE_FUNCTIONS)
    longhands = data.LONGHAND_SUB_PROPERTIES_OF_SHORTHAND_PROPERTIES
    assert longhands['margin'] == {'margin-top', 'margin-right', 'margin-bottom', 'margin-left'}
    assert 'background-color' in longhands['background']


def test_tables_are_read_only() -> None:
    longhands = data.LONGHAND_SUB_PROPERTIES_OF_SHORTHAND_PROPERTIES
    with pytest.raises(TypeError):
        longhands['x'] = frozenset()  # ty: ignore[invalid-assignment]
